#include "i2c_soft.h"
unsigned char data sample _at_ 0x30;
void main(void) {
    P1 = 0xC0;
    while (1) {
        i2c_start(); i2c_write(0x90); i2c_write(0x40);
        i2c_start(); i2c_write(0x91);
        i2c_read(1); /* stale byte, ACK */
        sample = i2c_read(0); /* fresh byte, NACK */
        i2c_stop();
        i2c_start(); i2c_write(0x90);
        i2c_write(0x40); i2c_write(sample);
        i2c_stop();
    }
}

